// ============================================
// Design Tokens - Kajaia Bonds Trading Platform
// ============================================

// Typography
$font-family-base: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
$font-family-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

$font-size-xs: 0.75rem;    // 12px
$font-size-sm: 0.8125rem;  // 13px
$font-size-base: 0.875rem; // 14px
$font-size-md: 1rem;       // 16px
$font-size-lg: 1.125rem;   // 18px
$font-size-xl: 1.5rem;     // 24px
$font-size-2xl: 2rem;      // 32px
$font-size-3xl: 2.5rem;    // 40px

$font-weight-regular: 400;
$font-weight-medium: 500;
$font-weight-semibold: 600;
$font-weight-bold: 700;

$line-height-tight: 1.2;
$line-height-base: 1.5;
$line-height-relaxed: 1.6;

// Spacing (8px base unit)
$space-1: 0.25rem;  // 4px
$space-2: 0.5rem;   // 8px
$space-3: 0.75rem;  // 12px
$space-4: 1rem;     // 16px
$space-5: 1.25rem;  // 20px
$space-6: 1.5rem;   // 24px
$space-8: 2rem;     // 32px
$space-10: 2.5rem;  // 40px
$space-12: 3rem;    // 48px
$space-16: 4rem;    // 64px

// Border Radius
$radius-sm: 6px;
$radius-md: 8px;
$radius-lg: 12px;
$radius-xl: 16px;
$radius-full: 9999px;

// Shadows
$shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.2);
$shadow-md: 0 4px 12px rgba(0, 0, 0, 0.25);
$shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.3);
$shadow-xl: 0 16px 40px rgba(0, 0, 0, 0.4);

// Transitions
$transition-fast: 0.1s ease;
$transition-base: 0.15s ease;
$transition-slow: 0.25s ease;

// Breakpoints
$breakpoint-sm: 640px;
$breakpoint-md: 768px;
$breakpoint-lg: 1024px;
$breakpoint-xl: 1280px;

// Layout
$container-max-width: 1120px;
$container-padding: $space-6;

// Z-Index Scale
$z-dropdown: 100;
$z-sticky: 200;
$z-modal-backdrop: 400;
$z-modal: 500;
$z-tooltip: 600;

// ============================================
// Neutral Colors (shared across themes)
// ============================================
$neutral-50: #fafafa;
$neutral-100: #f5f5f5;
$neutral-200: #e5e5e5;
$neutral-300: #d4d4d4;
$neutral-400: #a3a3a3;
$neutral-500: #737373;
$neutral-600: #525252;
$neutral-700: #404040;
$neutral-800: #262626;
$neutral-900: #171717;
$neutral-950: #0a0a0a;

// Semantic Colors (shared)
$success-400: #4ade80;
$success-500: #22c55e;
$success-600: #16a34a;

$error-400: #f87171;
$error-500: #ef4444;
$error-600: #dc2626;

$warning-400: #fbbf24;
$warning-500: #f59e0b;
$warning-600: #d97706;

$info-400: #60a5fa;
$info-500: #3b82f6;
$info-600: #2563eb;

