.badge {
  display: inline-flex;
  align-items: center;
  padding: $space-1 $space-2;
  border-radius: $radius-full;
  font-size: $font-size-xs;
  font-weight: $font-weight-medium;

  &--success {
    background: rgba($success-500, 0.15);
    color: $success-400;
    border: 1px solid rgba($success-500, 0.3);
  }

  &--error {
    background: rgba($error-500, 0.15);
    color: $error-400;
    border: 1px solid rgba($error-500, 0.3);
  }

  &--warning {
    background: rgba($warning-500, 0.15);
    color: $warning-400;
    border: 1px solid rgba($warning-500, 0.3);
  }

  &--info {
    background: rgba($user-primary-500, 0.15);
    color: $user-primary-400;
    border: 1px solid rgba($user-primary-500, 0.3);
  }

  &--neutral {
    background: $user-bg-elevated;
    color: $user-text-secondary;
    border: 1px solid $user-border-default;
  }
}

// Modal Component
.modal {
  &__backdrop {
    position: fixed;
    inset: 0;
    background: rgba($user-bg-base, 0.8);
    backdrop-filter: blur(4px);
    @include flex-center;
    padding: $space-4;
    z-index: $z-modal-backdrop;
  }

  &__container {
    width: 100%;
    max-width: 560px;
    max-height: 90vh;
    overflow-y: auto;
    background: $user-bg-surface;
    border: 1px solid $user-border-default;
    border-radius: $radius-xl;
    box-shadow: $shadow-xl;
    z-index: $z-modal;
  }

  &__header {
    @include flex-between;
    padding: $space-4 $space-6;
    border-bottom: 1px solid $user-border-subtle;
  }

  &__title {
    @include text-heading;
    margin: 0;
  }

  &__body {
    padding: $space-6;
  }

  &__footer {
    display: flex;
    justify-content: flex-end;
    gap: $space-3;
    padding: $space-4 $space-6;
    border-top: 1px solid $user-border-subtle;
  }
}

// Alert Messages
.alert {
  padding: $space-3 $space-4;
  border-radius: $radius-md;
  font-size: $font-size-sm;

  &--error {
    background: rgba($error-500, 0.1);
    border: 1px solid rgba($error-500, 0.3);
    color: $error-400;
  }

  &--success {
    background: rgba($success-500, 0.1);
    border: 1px solid rgba($success-500, 0.3);
    color: $success-400;
  }

  &--info {
    background: rgba($user-primary-500, 0.1);
    border: 1px solid rgba($user-primary-500, 0.3);
    color: $user-primary-400;
  }
}

// Link
.link {
  color: $user-primary-400;
  text-decoration: none;
  transition: color $transition-base;

  &:hover {
    color: $user-primary-500;
    text-decoration: underline;
  }
}

// Utility Classes
.text-muted {
  color: $user-text-muted;
}

.text-secondary {
  color: $user-text-secondary;
}

.mono {
  @include text-mono;
}

