2	import { CommonModule } from '@angular/common';
3	import { ToastService, Toast, ToastType } from '../../../core/services/toast.service';
4	
5	@Component({
6	  selector: 'app-toast',
7	  standalone: true,
8	  imports: [CommonModule],
9	  template: `
10	    <div class="toast-container" aria-live="polite" aria-atomic="false">
11	      @for (toast of toastService.toasts(); track toast.id; let i = $index) {
12	        <div
13	          class="toast"
14	          [class]="'toast--' + toast.type"
15	          role="alert"
16	          [attr.aria-label]="getAriaLabel(toast)"
17	          tabindex="0"
18	          (keydown.escape)="toastService.dismiss(toast.id)"
19	          (keydown.enter)="handleAction(toast)">
20	          <span class="toast__icon" aria-hidden="true">
21	            @switch (toast.type) {
22	              @case ('success') { <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M20 6L9 17l-5-5"/></svg> }
23	              @case ('error') { <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M18 6L6 18M6 6l12 12"/></svg> }
24	              @case ('warning') { <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M12 9v4m0 4h.01M12 3l9.5 16.5H2.5L12 3z"/></svg> }
25	              @case ('info') { <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4h.01"/></svg> }
26	            }
27	          </span>
28	          <span class="toast__message">{{ toast.message }}</span>
29	          @if (toast.action) {
30	            <button
31	              class="toast__action"
32	              (click)="handleAction(toast)"
33	              [attr.aria-label]="toast.action.label">
34	              {{ toast.action.label }}
35	            </button>
36	          }
37	          <button
38	            class="toast__close"
39	            (click)="toastService.dismiss(toast.id)"
40	            aria-label="Dismiss notification"
41	            tabindex="0">
42	            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
43	          </button>
44	        </div>
45	      }
46	    </div>
47	  `,
48	  styleUrl: './toast.component.scss'
49	})
50	export class ToastComponent {
51	  readonly toastService = inject(ToastService);
52	
53	  private readonly typeLabels: Record<ToastType, string> = {
54	    success: 'Success',
55	    error: 'Error',
56	    warning: 'Warning',
57	    info: 'Information'
58	  };
59	
60	  getAriaLabel(toast: Toast): string {
61	    const typeLabel = this.typeLabels[toast.type];
62	    const actionHint = toast.action ? `. Press Enter to ${toast.action.label.toLowerCase()}.` : '';
63	    return `${typeLabel}: ${toast.message}${actionHint} Press Escape to dismiss.`;
64	  }
65	
66	  handleAction(toast: Toast): void {
67	    if (toast.action) {
68	      toast.action.callback();
69	      this.toastService.dismiss(toast.id);
70	    }
71	  }
72	}
