1	@use '../../../../styles/variables' as *;
2	@use '../../../../styles/mixins' as *;
3	
4	// User theme colors - Light with blue tint
5	$auth-bg-base: #f8fafc;
6	$auth-bg-surface: #ffffff;
7	$auth-bg-elevated: #f0f9ff;
8	$auth-primary: #06b6d4;
9	$auth-secondary: #3b82f6;
10	$auth-text-primary: #0c4a6e;
11	$auth-text-secondary: #0369a1;
12	$auth-text-muted: #64748b;
13	$auth-border: #bae6fd;
14	
15	:host {
16	  display: block;
17	  min-height: 100vh;
18	  background: linear-gradient(135deg, #f0f9ff 0%, #f8fafc 50%, #ecfeff 100%);
19	  @include flex-center;
20	  padding: $space-6;
21	}
22	
23	// ============================================
24	// Auth Container Block
25	// ============================================
26	.auth-container {
27	  width: 100%;
28	  max-width: 420px;
29	  padding: $space-8;
30	  background: $auth-bg-surface;
31	  border: 1px solid $auth-border;
32	  border-radius: $radius-xl;
33	  box-shadow: 0 10px 40px rgba(6, 182, 212, 0.1), 0 4px 12px rgba(0, 0, 0, 0.05);
34	  transition: max-width $transition-base;
35	
36	  // Wider, more square footprint for the multi-field registration form.
37	  &.wide {
38	    max-width: 680px;
39	  }
40	
41	  h2 {
42	    @include text-title;
43	    text-align: center;
44	    margin-bottom: $space-4;
45	    color: $auth-text-primary;
46	  }
47	}
48	
49	// ============================================
50	// Toggle Button
51	// ============================================
52	.toggle-btn {
53	  display: block;
54	  width: 100%;
55	  padding: $space-2 $space-4;
56	  margin-bottom: $space-6;
57	  background: $auth-bg-elevated;
58	  border: 1px solid $auth-border;
59	  border-radius: $radius-md;
60	  color: $auth-text-muted;
61	  font-size: $font-size-sm;
62	  font-weight: $font-weight-medium;
63	  cursor: pointer;
64	  transition: all $transition-base;
65	  @include hover-lift;
66	
67	  &:hover {
68	    background: rgba($auth-primary, 0.1);
69	    border-color: $auth-primary;
70	    color: $auth-text-primary;
71	  }
72	}
73	
74	// ============================================
75	// Auth Form Block
76	// ============================================
77	.auth-form {
78	  display: flex;
79	  flex-direction: column;
80	  gap: $space-4;
81	
82	  label {
83	    display: flex;
84	    flex-direction: column;
85	    gap: $space-2;
86	    font-size: $font-size-sm;
87	    font-weight: $font-weight-medium;
88	    color: $auth-text-muted;
89	  }
90	
91	  input {
92	    padding: $space-3;
93	    background: $auth-bg-surface;
94	    border: 1px solid $auth-border;
95	    border-radius: $radius-md;
96	    color: $auth-text-primary;
97	    font-size: $font-size-sm;
98	    transition: all $transition-base;
99	
100	    &::placeholder {
101	      color: $auth-text-muted;
102	    }
103	
104	    &:focus {
105	      outline: none;
106	      border-color: $auth-primary;
107	      box-shadow: 0 0 0 3px rgba($auth-primary, 0.1);
108	    }
109	  }
110	
111	  select {
112	    padding: $space-3;
113	    background: $auth-bg-surface;
114	    border: 1px solid $auth-border;
115	    border-radius: $radius-md;
116	    color: $auth-text-primary;
117	    font-size: $font-size-sm;
118	    cursor: pointer;
119	    transition: all $transition-base;
120	
121	    &:focus {
122	      outline: none;
123	      border-color: $auth-primary;
124	      box-shadow: 0 0 0 3px rgba($auth-primary, 0.1);
125	    }
126	  }
127	
128	  button[type="submit"] {
129	    margin-top: $space-2;
130	    padding: $space-3 $space-4;
131	    background: linear-gradient(135deg, $auth-primary, $auth-secondary);
132	    border: none;
133	    border-radius: $radius-md;
134	    color: #ffffff;
135	    font-size: $font-size-sm;
136	    font-weight: $font-weight-semibold;
137	    cursor: pointer;
138	    transition: all $transition-base;
139	    @include hover-lift;
140	
141	    &:hover:not(:disabled) {
142	      box-shadow: 0 4px 16px rgba($auth-primary, 0.35);
143	    }
144	
145	    &:disabled {
146	      opacity: 0.5;
147	      cursor: not-allowed;
148	    }
149	  }
150	}
151	
152	// ============================================
153	// Register Grid (symmetric two-column layout)
154	// ============================================
155	.register-grid {
156	  display: grid;
157	  grid-template-columns: 1fr 1fr;
158	  gap: $space-4 $space-5;
159	
160	  label {
161	    margin: 0;
162	  }
163	
164	  // Full-width rows: address + the submit button.
165	  .span-2 {
166	    grid-column: 1 / -1;
167	  }
168	
169	  button[type="submit"] {
170	    width: 100%;
171	  }
172	
173	  // Collapse to a single column on narrow screens.
174	  @media (max-width: 560px) {
175	    grid-template-columns: 1fr;
176	
177	    .span-2 {
178	      grid-column: 1 / -1;
179	    }
180	  }
181	}
182	
183	// ============================================
184	// Messages
185	// ============================================
186	.info {
187	  margin-top: $space-4;
188	  padding: $space-3;
189	  background: rgba($success-500, 0.1);
190	  border: 1px solid rgba($success-500, 0.3);
191	  border-radius: $radius-md;
192	  color: $success-400;
193	  font-size: $font-size-sm;
194	}
195	
196	.error {
197	  margin-top: $space-4;
