    transition: all $transition-base;

    &:focus {
      outline: none;
      border-color: $auth-primary;
      box-shadow: 0 0 0 3px rgba($auth-primary, 0.1);
    }
  }

  button[type="submit"] {
    margin-top: $space-2;
    padding: $space-3 $space-4;
    background: linear-gradient(135deg, $auth-primary, $auth-secondary);
    border: none;
    border-radius: $radius-md;
    color: #ffffff;
    font-size: $font-size-sm;
    font-weight: $font-weight-semibold;
    cursor: pointer;
    transition: all $transition-base;
    @include hover-lift;

    &:hover:not(:disabled) {
      box-shadow: 0 4px 16px rgba($auth-primary, 0.35);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
}

// ============================================
// Register Grid (symmetric two-column layout)
// ============================================
.register-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: $space-4 $space-5;

  label {
    margin: 0;
  }

  // Full-width rows: address + the submit button.
  .span-2 {
    grid-column: 1 / -1;
  }

  button[type="submit"] {
    width: 100%;
  }

  // Collapse to a single column on narrow screens.
  @media (max-width: 560px) {
    grid-template-columns: 1fr;

    .span-2 {
      grid-column: 1 / -1;
    }
  }
}

// ============================================
// Messages
// ============================================
.info {
  margin-top: $space-4;
  padding: $space-3;
  background: rgba($success-500, 0.1);
  border: 1px solid rgba($success-500, 0.3);
  border-radius: $radius-md;
  color: $success-400;
  font-size: $font-size-sm;
}

.error {
  margin-top: $space-4;
  padding: $space-3;
  background: rgba($error-500, 0.1);
  border: 1px solid rgba($error-500, 0.3);
  border-radius: $radius-md;
  color: $error-400;
  font-size: $font-size-sm;
}

// ============================================
// Back Link
// ============================================
.back-link {
  display: inline-block;
  margin-top: $space-6;
  color: $auth-primary;
  font-size: $font-size-sm;
  text-decoration: none;
  transition: color $transition-base;

  &:hover {
    color: lighten($auth-primary, 10%);
    text-decoration: underline;
  }
}

