input.content:
@use '../../../../styles/variables' as *;

// ── Backdrop ──────────────────────────────────────────────────
.scan-backdrop {
  position: fixed;
  inset: 0;
  background: rgba($ink, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: $z-modal-backdrop;
  padding: $space-4;

  // Full screen on small phones
  @media (max-width: 479px) {
    padding: 0;
    align-items: stretch;
  }
}

// ── Modal ─────────────────────────────────────────────────────
.scan-modal {
  position: relative;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-xl;
  width: 100%;
  max-width: 480px;
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  padding: $space-8 $space-6 $space-6;
  box-shadow: $shadow-pop;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: $space-5;

  @media (max-width: 479px) {
    max-width: none;
    max-height: none;
    height: 100dvh;
    border: none;
    border-radius: 0;
    padding: $space-8 $space-4 max($space-4, env(safe-area-inset-bottom));
  }

  &__close {
    position: absolute;
    top: $space-2;
    right: $space-2;
    width: $ctl-h;
    height: $ctl-h;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    font-size: 24px;
    color: $ink-2;
    cursor: pointer;
    border-radius: $radius-md;
    line-height: 1;
    transition: background 0.15s, color 0.15s;

    &:hover { background: $page; color: $ink; }
    &:focus-visible { outline: none; box-shadow: $focus-ring; }
  }

  &__header {
    text-align: center;
    width: 100%;
    padding-inline: $space-6;
  }

  &__title {
    font-size: $font-size-lg;
    font-weight: $font-weight-bold;
    color: $ink;
    margin: 0 0 $space-1;
  }

  &__subtitle {
    font-size: $font-size-base;
    color: $ink-2;
    margin: 0;
  }

  // ── Camera ───────────────────────────────────────────────
  &__camera-wrap {
    position: relative;
    width: min(100%, 320px);
    aspect-ratio: 1 / 1;
    border-radius: $radius-lg;
    overflow: hidden;
    background: #000;
  }

  &__video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;

    &--hidden {
      display: none;
    }
  }

  // ── Viewfinder overlay ────────────────────────────────────
  &__viewfinder {
    position: absolute;
    inset: 20px;
    pointer-events: none;
  }

  &__corner {
    position: absolute;
    width: 28px;
    height: 28px;
    border-color: $blue-600;
    border-style: solid;
    // dark outline keeps the brackets visible over bright video
    filter: drop-shadow(0 0 1px #fff) drop-shadow(0 0 2px rgba(0, 0, 0, 0.6));

    &--tl { top: 0; left: 0; border-width: 4px 0 0 4px; border-radius: 4px 0 0 0; }
    &--tr { top: 0; right: 0; border-width: 4px 4px 0 0; border-radius: 0 4px 0 0; }
    &--bl { bottom: 0; left: 0; border-width: 0 0 4px 4px; border-radius: 0 0 0 4px; }
    &--br { bottom: 0; right: 0; border-width: 0 4px 4px 0; border-radius: 0 0 4px 0; }
  }

  &__scan-line {
    position: absolute;
    left: 0; right: 0;
    height: 3px;
    background: $blue-600;
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.8), 0 0 8px rgba($blue-600, 0.8);
    animation: scan 2s ease-in-out infinite;
  }

  // ── Token details ─────────────────────────────────────────
  &__token-details {
    width: 100%;
    background: $surface;
    border: 1px solid $line;
    border-radius: $radius-lg;
    overflow: hidden;
  }

  // ── Footer ───────────────────────────────────────────────
  &__footer {
    width: 100%;
    display: flex;
    justify-content: center;
    gap: $space-3;

    &--confirm {
      justify-content: space-between;
    }

    .scan-btn {
      flex: 1;
    }

    // Stack on mobile, primary action first
    @media (max-width: 479px) {
      flex-direction: column-reverse;
      margin-top: auto;
    }
  }

  // ── State (loading / error) ───────────────────────────────
  &__state {
    display: flex;
    flex-direction: column;
