  align-items: center;
  padding: 10px 16px;
  border-bottom: 1px solid $border;

  &:last-child { border-bottom: none; }

  &__label {
    font-size: 0.78rem;
    font-weight: 600;
    color: $text-muted;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    flex-shrink: 0;
    margin-right: 12px;
  }

  &__value {
    font-size: 0.88rem;
    color: $text;
    font-weight: 500;
    text-align: right;

    &--highlight {
      color: $primary;
      font-size: 1rem;
      font-weight: 700;
    }
  }
}

.mono { font-family: 'JetBrains Mono', monospace; }

.token-detail-row--mono {
  align-items: flex-start;

  .token-detail-row__value {
    word-break: break-all;
    font-size: 0.78rem;
  }
}

// ── Scan line animation ────────────────────────────────────────
@keyframes scan {
  0%   { top: 0; opacity: 0; }
  10%  { opacity: 1; }
  90%  { opacity: 1; }
  100% { top: 100%; opacity: 0; }
}

// ── Spinner ───────────────────────────────────────────────────
.scan-spinner {
  width: 40px;
  height: 40px;
  border: 3px solid $border;
  border-top-color: $primary;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

// ── Buttons ───────────────────────────────────────────────────
.scan-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s;

  &--ghost {
    background: transparent;
    border: 1px solid $border;
    color: $text-muted;
    &:hover { background: $primary-bg; color: $text; border-color: $primary; }
  }

  &--confirm {
    background: $success;
    color: #fff;
    &:hover { background: darken($success, 6%); box-shadow: 0 4px 12px rgba($success, 0.3); }
    &:disabled { opacity: 0.5; cursor: not-allowed; }
  }
}

