  &__steps { display: flex; align-items: flex-start; margin-top: 56px; }
  &__step { flex: 1; text-align: center; padding: 0 24px; }
  &__step-number {
    width: 36px; height: 36px; border-radius: 50%;
    background: #1a56db; color: #fff;
    font-weight: 700; font-size: 0.9rem;
    display: inline-flex; align-items: center; justify-content: center; margin-bottom: 16px;
  }
  &__step-icon { font-size: 2.4rem; display: block; margin-bottom: 16px; }
  &__step-title { font-size: 1.15rem; font-weight: 700; color: #111827; margin: 0 0 10px; }
  &__step-desc { font-size: 0.95rem; color: #6b7280; line-height: 1.6; margin: 0; }
  &__connector {
    width: 80px; height: 2px;
    background: linear-gradient(90deg, #bfdbfe, #1a56db);
    margin-top: 60px; flex-shrink: 0;
  }
}

// ── Value Proposition ─────────────────────────────────────────────────────────
.value-prop { padding: 96px 0; background: #f9fafb; }

.vp {
  &__cards {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 56px;
  }
  &__card {
    background: #fff; border: 1px solid #e5e7eb; border-radius: 16px; padding: 32px 28px;
    transition: box-shadow 0.2s, transform 0.2s;
    &:hover { box-shadow: 0 8px 24px rgba(26,86,219,0.1); transform: translateY(-2px); }
  }
  &__card-icon { font-size: 2rem; margin-bottom: 16px; display: block; }
  &__card-title { font-size: 1.05rem; font-weight: 700; color: #111827; margin: 0 0 10px; }
  &__card-desc { font-size: 0.92rem; color: #6b7280; line-height: 1.6; margin: 0; }
}

// ── Trust ─────────────────────────────────────────────────────────────────────
.trust {
  padding: 96px 0; background: #fff; text-align: center;

  &__mission {
    max-width: 640px; margin: 0 auto 48px;
    font-size: 1.05rem; color: #4b5563; line-height: 1.75;
  }
  &__badges { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; margin-bottom: 0; }
  &__badge {
    display: flex; align-items: center; gap: 10px;
    background: #f0f5ff; border: 1px solid #bfdbfe; border-radius: 100px; padding: 10px 20px;
    &-icon { font-size: 1.1rem; }
    &-text { font-size: 0.875rem; font-weight: 500; color: #1e40af; }
  }
}

// ── FAQ ───────────────────────────────────────────────────────────────────────
.faq {
  padding: 96px 0; background: #f9fafb;

  &__list { margin: 48px auto 0; max-width: 760px; }
  &__item {
    border: 1px solid #e5e7eb; border-radius: 12px; margin-bottom: 12px;
    background: #fff; overflow: hidden; transition: box-shadow 0.2s;
    &--open { box-shadow: 0 4px 16px rgba(26,86,219,0.08); border-color: #bfdbfe; }
  }
  &__btn {
    width: 100%; display: flex; justify-content: space-between; align-items: center;
    padding: 20px 24px; background: none; border: none; cursor: pointer;
    font-size: 1rem; font-weight: 600; color: #111827; text-align: left; gap: 16px;
    min-height: 44px; font-family: inherit;
    &:focus-visible { outline: 2px solid #1a56db; outline-offset: -2px; }
    &:hover { background: #f9fafb; }
  }
  &__chevron { font-size: 1.3rem; color: #1a56db; flex-shrink: 0; }
  &__answer { padding: 0 24px 20px; color: #4b5563; font-size: 0.95rem; line-height: 1.7; margin: 0; }
}

// ── Bottom CTA ────────────────────────────────────────────────────────────────
.bottom-cta {
  padding: 96px 0;
  background: linear-gradient(135deg, #1a56db 0%, #1648c0 100%);
  text-align: center;

  &__inner { display: flex; flex-direction: column; align-items: center; gap: 20px; }
  &__title { font-size: clamp(1.6rem, 3vw, 2.25rem); font-weight: 800; color: #fff; margin: 0; letter-spacing: -0.5px; }
  &__sub { font-size: 1.05rem; color: rgba(255,255,255,0.85); margin: 0; max-width: 480px; }
  &__btn { background: #fff; color: #1a56db; &:hover { background: #f0f5ff; box-shadow: 0 4px 20px rgba(0,0,0,0.15); } }
}

// ── Footer ────────────────────────────────────────────────────────────────────
.footer {
  background: #111827; padding: 48px 0 32px;

  &__inner {
    max-width: 1200px; margin: 0 auto; padding: 0 24px;
    display: flex; flex-direction: column; align-items: center; gap: 24px; text-align: center;
  }
  &__logo { display: inline-flex; align-items: center; gap: 8px; color: #fff; font-weight: 700; font-size: 1.15rem; }
  &__tagline { color: #9ca3af; font-size: 0.875rem; margin: 6px 0 0; }
  &__links { display: flex; gap: 32px; flex-wrap: wrap; justify-content: center; }
  &__link { color: #d1d5db; font-size: 0.875rem; transition: color 0.2s; &:hover { color: #fff; } }
  &__copy { color: #6b7280; font-size: 0.8rem; margin: 0; }
}

// ── Responsive ────────────────────────────────────────────────────────────────
@media (max-width: 1023px) {
  .vp__cards { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 767px) {
  .hero {
    padding: 60px 0 50px;
    &__inner { grid-template-columns: 1fr; gap: 40px; }
  }
  .token-graphic { padding: 24px 20px; gap: 10px; }
  .token { width: 70px; &__icon { width: 52px; height: 52px; font-size: 1.3rem; } }

  .hiw__steps { flex-direction: column; align-items: center; }
  .hiw__step { padding: 0; max-width: 320px; width: 100%; }
  .hiw__connector { width: 2px; height: 40px; background: linear-gradient(180deg, #bfdbfe, #1a56db); }

  .vp__cards { grid-template-columns: 1fr; }
}

