    display: flex;
    align-items: center;
    gap: $space-6;
    flex: 1;
    justify-content: center;

    @media (max-width: 767px) { display: none; }
  }

  &__link {
    display: inline-flex;
    align-items: center;
    min-height: $ctl-h;
    color: $ink;
